ROOT, DATA, OUT = design.ROOT, design.DATA, design.OUT
OLD = ROOT / 'data/trb_reassessment_20261028/fixed_support_capacity_panel/design.json'


def certificate_check(problem, lead, certificate, result):
    """Recompute every Bellman alternative from raw arrays and saved integers."""
    states = {(row['t'], row['mask']): row for row in certificate}
    paths, target, weights = problem['paths'], problem['target'], problem['weights']
    h, t0, checked = problem['horizon'], problem['t0'], 0

    def groups(mask, key):
        bins = defaultdict(int)
        for s in range(len(paths)):
            if mask & (1 << s):
                bins[key(s)] |= 1 << s
        return tuple(bins.values())

    for (t, mask), row in states.items():
        members = [s for s in range(len(paths)) if mask & (1 << s)]
        assert members and t0 <= t <= h
        assert len({tuple(target[s][t0:t]) for s in members}) == 1
        if t == h:
            expected, choice = 0, ['end']
        elif len({target[s][t] for s in members}) == 1:
            values = [states[(t+1, child)]['value']
                      for child in groups(mask, lambda s: paths[s][t])]
            expected = None if None in values else sum(values)
            choice = ['advance'] if expected is not None else ['infeasible']
        else:
            candidates = []
            for j in range(t0, h):
                if max(t0, j-lead) > t:
                    continue
                parts = groups(mask, lambda s: paths[s][j])
                if len(parts) <= 1:
                    continue
                values = [states[(t, child)]['value'] for child in parts]
                cost = None if None in values else sum(weights[s] for s in members)+sum(values)
                checked += 1
                if cost is not None:
                    candidates.append((cost, j))
            expected = min((c for c, _ in candidates), default=None)
            choice = row['choice']
            if expected is None:
                assert choice == ['infeasible']
            else:
                assert choice[0] == 'query' and (expected, choice[1]) in candidates
        assert row['value'] == expected
        if t == h or len({target[s][t] for s in members}) == 1:
            assert row['choice'] == choice
    initial = groups((1 << len(paths))-1, lambda s: tuple(paths[s][:t0]))
    initial_values = [states[(t0, m)]['value'] for m in initial]
    expected_total = None if None in initial_values else sum(initial_values)
    assert result['weighted_cost'] == expected_total
    return dict(passed=True, states=len(states), query_alternatives=checked)


def unrestricted_oracle(problem, lead):
    """Small-instance enumeration permits queries even when action is known."""
    paths, targets, weights = problem['paths'], problem['target'], problem['weights']
    h, t0 = problem['horizon'], problem['t0']

    def partition(mask, key):
        groups = defaultdict(int)
        for s, path in enumerate(paths):
            if mask & (1 << s):
                groups[key(s, path)] |= 1 << s
        return tuple(groups.values())

    @lru_cache(None)
    def value(t, mask):
        if t == h:
            return 0
        options = []
        if len({targets[s][t] for s in range(len(paths)) if mask & (1 << s)}) == 1:
            children = [value(t+1, child) for child in partition(mask, lambda s, p: p[t])]
            if None not in children:
                options.append(sum(children))
        for j in range(t0, h):
            if j-lead > t:
                continue
            parts = partition(mask, lambda s, p: p[j])
            if len(parts) <= 1:
                continue
            children = [value(t, child) for child in parts]
            if None not in children:
                options.append(sum(weights[s] for s in range(len(paths)) if mask & (1 << s))+sum(children))
        return min(options, default=None)

    initial = partition((1 << len(paths))-1, lambda s, p: tuple(p[:t0]))
    costs = [value(t0, m) for m in initial]
    return None if None in costs else sum(costs)


def static_replay(problem, lead, slots):
    """General information partition, with no critical-pair shortcut."""
    paths, t0, h = problem['paths'], problem['t0'], problem['horizon']
    actual = [list(problem['prefix']) for _ in paths]
    for t in range(t0, h):
        groups = defaultdict(list)
        delivered = [j for j in slots if max(t0, j-lead) <= t]
        for s, path in enumerate(paths):
            groups[(tuple(path[:t]), tuple(path[j] for j in delivered))].append(s)
        for members in groups.values():
            assert len({tuple(actual[s]) for s in members}) == 1
            previous = actual[members[0]][-1] if t else 0
            u = max(previous, max(problem['bounds'][s][t] for s in members))
            for s in members:
                actual[s].append(u)
    equal = actual == problem['target']
    for s, path in enumerate(paths):
        assert all(0 <= u <= k for u, k in zip(design.base.increments(actual[s]), problem['caps']))
        completed, _, _ = design.base.physical(actual[s], path, problem['n'], problem['lag'])
        assert completed == problem['references'][s]
    return equal


def solve_one(problem, lead, small_oracle=False, include_certificate=True):
    begin = perf_counter()
    engine = design.AdaptiveDesign(problem, lead)
    adaptive = engine.solve()
    cert = engine.certificate()
    checked = certificate_check(problem, lead, cert, adaptive)
    assert adaptive['feasible'] == (lead >= problem['L_star'])
    static = design.menu_cover(problem, lead)
    assert static['feasible'] == adaptive['feasible']
    rows = engine.replay() if adaptive['feasible'] else []
    if adaptive['feasible']:
        assert adaptive['expected_queries'] <= static['optimal_message_count'] + 1e-12
        assert static_replay(problem, lead, static['selected_slots'])
    if small_oracle:
        assert unrestricted_oracle(problem, lead) == adaptive['weighted_cost']
        oracle_static = None
        for count in range(problem['horizon']-problem['t0']+1):
            for slots in combinations(range(problem['t0'], problem['horizon']), count):
                if static_replay(problem, lead, slots):
                    oracle_static = count
                    break
            if oracle_static is not None:
                break
        assert oracle_static == static.get('optimal_message_count')
    return dict(lead=lead, L_star=problem['L_star'], adaptive=adaptive, static=static,
                certificate_check=checked, certificate=cert if include_certificate else None,
                replay=rows, elapsed_seconds=perf_counter()-begin)


def synthetic_smoke():
    cases = [dict(n=2, caps=[1]*6, lag=1, delta=1,
                  service=[[0,0,2,0,0,0], [0,0,0,0,0,2]], probabilities=['1/2']*2),
             dict(n=1, caps=[1,0,0,1], lag=0, delta=1,
                  service=[[0,0,0,1],[0,1,0,0],[0,0,1,0]], probabilities=['1/3']*3)]
    rng = random.Random(20261028)
    for _ in range(42):
        h = rng.randint(3,6)
        count = rng.randint(2,5)
        raw_weights = [rng.randint(1,4) for _ in range(count)]
        cases.append(dict(n=rng.randint(1,3), caps=[rng.randint(0,2) for _ in range(h)],
                          lag=rng.randint(0,1), delta=1,
                          service=[[rng.randint(0,2) for _ in range(h)] for _ in range(count)],
                          probabilities=[str(Fraction(w,sum(raw_weights))) for w in raw_weights]))
    checked, omitted, totals = [], [], dict(states=0, query_alternatives=0)
    for index, case in enumerate(cases):
        empty = design.prepare(case)
        if empty is None:
            omitted.append(index)
            continue
        prefix = design.base.frontier(empty['paths'], empty['bounds'], [], -1)[0][:1]
        for executed in ([], prefix):
            problem = design.prepare(case, executed)
            for lead in range(-1, problem['horizon']):
                row = solve_one(problem, lead, small_oracle=True, include_certificate=False)
                totals['states'] += row['certificate_check']['states']
                totals['query_alternatives'] += row['certificate_check']['query_alternatives']
                checked.append(dict(case=index, t0=len(executed), lead=lead,
                                    optimum=row['adaptive']['expected_queries_exact']))
    # Information complementarity in an integer airport instance.
    p = design.prepare(cases[1])
    waiting = []
    for slots in ([],[1],[2],[1,2]):
        paths, plans = p['paths'], [[] for _ in p['paths']]
        for t in range(p['horizon']):
            groups = defaultdict(list)
            for s, path in enumerate(paths):
                groups[(tuple(path[:t]),tuple(path[j] for j in slots))].append(s)
            for members in groups.values():
                previous = plans[members[0]][-1] if t else 0
                u = max(previous,max(p['bounds'][s][t] for s in members))
                for s in members:
                    plans[s].append(u)
        values = [sum(design.base.physical(plan,path,p['n'],0)[1]) for plan,path in zip(plans,paths)]
        waiting.append(dict(slots=slots, path_waiting=values, mean=str(Fraction(sum(values),len(values)))))
    assert [r['mean'] for r in waiting] == ['2','2','2','1']
    return dict(passed=True, generated_cases=len(cases), complete_support_cases=len(cases)-len(omitted),
                incomplete_support_cases=omitted, checked=checked, totals=totals, complementarity=waiting)


def public_smoke():
    manifest = design.read(OLD)
    results = []
    for row in manifest['rows']:
        if row['key'] not in manifest['smoke_keys']:
            continue
        path = ROOT / row['input_path']
        assert design.digest(path) == row['input_sha256']
        case = design.read(path)
        empty = design.prepare(case)
        if empty is None:
            results.append(dict(case_id=row['case_id'], complete=False))
            continue
        prefix = design.base.frontier(empty['paths'], empty['bounds'], [], -1)[0][:1]
        for executed in ([],prefix):
            problem = design.prepare(case,executed)
            for lead in sorted({case['lag'],problem['L_star'],case['lag']+2,len(case['caps'])-1}):
                result = solve_one(problem,lead)
                result.update(case_id=row['case_id'],key=row['key'],capacity_label=row['capacity_label'],
                              complete=True,t0=len(executed))
                results.append(result)
                print(row['case_id'],len(executed),lead,result['adaptive']['expected_queries_exact'],
                      result['static'].get('optimal_message_count'),round(result['elapsed_seconds'],3),flush=True)
    return dict(passed=True, results=results)


def smoke():
    begin = perf_counter()
    synthetic = synthetic_smoke()
    design.save(OUT/'synthetic_smoke.json',synthetic)
    public = public_smoke()
    feasible = [r for r in public['results'] if r.get('adaptive',{}).get('feasible')]
    positive = [r for r in feasible if r['static']['relevant_messages'] > 0]
    useful = any(r['adaptive']['expected_queries'] < r['static']['optimal_message_count'] for r in positive)
    report = dict(passed=True, source_sha256=design.digest(Path(design.__file__)),
                  runner_sha256=design.digest(Path(__file__)), old_design_sha256=design.digest(OLD),
                  synthetic=synthetic, public=public, useful_adaptivity=useful,
                  max_public_seconds=max(r['elapsed_seconds'] for r in feasible),
                  elapsed_seconds=perf_counter()-begin)
    design.save(OUT/'smoke.json',report)
    print({k:v for k,v in report.items() if k not in ('synthetic','public')},flush=True)


def freeze():
    smoke_report = design.read(OUT/'smoke.json')
    assert smoke_report['passed'] and smoke_report['useful_adaptivity']
    assert smoke_report['source_sha256'] == design.digest(Path(design.__file__))
    old = design.read(OLD)
    report = dict(date='2026-10-28', frozen_before_panel=True,
                  physical_input_manifest=str(OLD.relative_to(ROOT)),
                  physical_input_manifest_sha256=design.digest(OLD),
                  smoke_sha256=design.digest(OUT/'smoke.json'),
                  source_sha256=design.digest(Path(design.__file__)),
                  runner_sha256=design.digest(Path(__file__)),
                  capacities=old['capacities'], rows=old['rows'],
                  prefixes=[0,1], lead_grid='Every integer L=-1,...,H-1', workers=2,
                  eligibility='All original positive-probability service paths clear the cohort; record every excluded support.',
                  reference='Capacity-specific earliest completions, frozen across all confirmation policies and leads.',
                  prefix='Empty; or capacity-specific past-observation frontier first cumulative release, fixed across all information policies.',
                  queries='Exact capacity value in one service slot; available from max(t0,j-L); unit confirmation cost; sequential immediate responses.',
                  methods=['exact static minimum menu','exact adaptive decision-timed confirmations'],
                  verification='Every Bellman alternative independently recomputed; each feasible policy replayed on every original path; static menu checked by general information classes.',
                  estimands='Window-equal averages for each capacity/prefix/lead; paired means on feasible common windows. Confirmations count coordination operations, with no conversion to monetary costs.')
    design.save(DATA/'design.json',report)
    print(dict(frozen=True,inputs=len(report['rows']),grid=report['lead_grid']),flush=True)


def csv_write(path, rows):
    path.parent.mkdir(parents=True,exist_ok=True)
    keys = list(dict.fromkeys(k for row in rows for k in row))
    with path.open('w',encoding='utf-8-sig',newline='') as stream:
        writer=csv.DictWriter(stream,fieldnames=keys)
        writer.writeheader()
        writer.writerows(rows)


def worker(row):
    begin = perf_counter()
    input_path = ROOT/row['input_path']
    assert design.digest(input_path) == row['input_sha256']
    case = design.read(input_path)
    empty = design.prepare(case)
    if empty is None:
        return dict(case_id=row['case_id'],key=row['key'],capacity_label=row['capacity_label'],
                    complete=False,elapsed_seconds=perf_counter()-begin), []
    prefix = design.base.frontier(empty['paths'],empty['bounds'],[],-1)[0][:1]
    records, detailed = [], []
    for executed in ([],prefix):
        problem=design.prepare(case,executed)
        before = None
        for lead in range(-1,problem['horizon']):
            result=solve_one(problem,lead)
            adaptive,static=result['adaptive'],result['static']
            if adaptive['feasible']:
                cost=adaptive['expected_queries']
                assert before is None or cost <= before
                before=cost
                full_wait=sum(problem['weights'][r['s']]*r['waiting'] for r in result['replay'])/problem['denominator']
            else:
                full_wait=None
            records.append(dict(case_id=row['case_id'],key=row['key'],airport=case['airport'],day=case['day'],
                                capacity_label=row['capacity_label'],t0=len(executed),N=case['n'],
                                lag=case['lag'],horizon=problem['horizon'],lead=lead,L_star=problem['L_star'],
                                feasible=adaptive['feasible'],expected_queries=adaptive['expected_queries'],
                                expected_queries_exact=adaptive['expected_queries_exact'],
                                static_queries=static.get('optimal_message_count'),
                                relevant_messages=static['relevant_messages'],
                                full_information_waiting=full_wait,
                                states=adaptive['states'],alternatives=result['certificate_check']['query_alternatives'],
                                elapsed_seconds=result['elapsed_seconds']))
            detailed.append(dict(t0=len(executed),**result))
    out=OUT/'runs'/f"{row['case_id']}.json.gz"
    out.parent.mkdir(parents=True,exist_ok=True)
    out.write_bytes(gzip.compress(__import__('json').dumps(dict(input=row,results=detailed),separators=(',',':')).encode(),mtime=0))
    return dict(case_id=row['case_id'],key=row['key'],capacity_label=row['capacity_label'],
                complete=True,run_path=str(out.relative_to(ROOT)),run_sha256=design.digest(out),
                elapsed_seconds=perf_counter()-begin),records


def panel():
    begin=perf_counter()
    manifest=design.read(DATA/'design.json')
    assert manifest['source_sha256'] == design.digest(Path(design.__file__))
    assert manifest['runner_sha256'] == design.digest(Path(__file__))
    assert manifest['physical_input_manifest_sha256'] == design.digest(OLD)
    coverage,records=[],[]
    with ProcessPoolExecutor(max_workers=min(manifest['workers'],os.cpu_count() or 1)) as pool:
        jobs={pool.submit(worker,row):row for row in manifest['rows']}
        for future in as_completed(jobs):
            cov,rows=future.result()
            coverage.append(cov)
            records.extend(rows)
            if len(coverage)%20 == 0 or len(coverage)==len(jobs):
                print('completed',len(coverage),'of',len(jobs),'seconds',round(perf_counter()-begin,1),flush=True)
    coverage.sort(key=lambda r:r['case_id'])
    records.sort(key=lambda r:(r['case_id'],r['t0'],r['lead']))
    csv_write(OUT/'coverage.csv',coverage)
    csv_write(OUT/'frontiers.csv',records)
    feasible=[r for r in records if r['feasible']]
    report=dict(passed=True,date='2026-10-28',design_sha256=design.digest(DATA/'design.json'),
                candidate_supports=len(coverage),complete_supports=sum(r['complete'] for r in coverage),
                excluded_supports=sum(not r['complete'] for r in coverage),prefixes=2,
                frontier_points=len(records),feasible_frontier_points=len(feasible),
                checked_bellman_states=sum(r['states'] for r in records),
                checked_query_alternatives=sum(r['alternatives'] for r in records),
                replayed_paths=len(feasible)*16,
                strict_adaptive_improvement_points=sum(r['expected_queries']<r['static_queries'] for r in feasible),
                elapsed_seconds=perf_counter()-begin,coverage=coverage)
    design.save(OUT/'panel.json',report)
    print({k:v for k,v in report.items() if k!='coverage'},flush=True)


def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--phase',choices=['smoke','freeze','panel'],required=True)
    args=parser.parse_args()
    if args.phase == 'smoke':
        smoke()
    elif args.phase == 'freeze':
        freeze()
    elif args.phase == 'panel':
        panel()


if __name__ == '__main__':
    main()
